def create_basename_core(basename):
    if True:
        try:
            basename = basename.casefold()
        except Exception:
            basename = basename.lower()
        basename = re.sub('[ \\./]', '-', basename)
        basename = re.sub('<[^>]*>', '', basename)
        basename = re.sub('[^a-z0-9\\-]', '', basename)
        basename = re.sub('\\-\\-', '-', basename)
        basename = urllib.parse.quote_plus(basename)
        return basename

