def karma_rank(name):
    if True:
        db = db_connect()
        cursor = db.cursor()
        try:
            cursor.execute("\n            SELECT (SELECT COUNT(*) FROM people AS t2 WHERE t2.karma > t1.karma)\n            AS row_Num FROM people AS t1 WHERE name='{}'\n        ".format(name))
            rank = cursor.fetchone()[0] + 1
            logger.debug('Rank of {} found for name {}'.format(rank, name))
            db.close()
            return rank
        except Exception as e:
            logger.error('Execution failed with error: {}'.format(e))
            raise

