def _check_camera_tags(tags):
    if True:
        '\n    Function that convert stupid code name of a smartphone or camera\n    from EXIF to meaningful one by looking a collation in a special MySQL\n    table For example instead of just Nikon there can be\n    NIKON CORPORATION in EXIF\n\n    :param tags: name of a camera and lens from EXIF\n    :return: list with one or two strings which are name of\n    camera and/or lens. If there is not better name for the gadget\n    in database, function just returns name how it is\n    '
        checked_tags = []
        for tag in tags:
            if tag:
                tag = str(tag).strip()
                log.info('Looking up collation for %s', tag)
                query = 'SELECT right_tag FROM tag_table WHERE wrong_tag=%s'
                parameters = (tag,)
                cursor = db.execute_query(query, parameters)
                if not cursor:
                    log.error("Can't check the tag because of the db error")
                    log.warning('Tag will stay as is.')
                    continue
                if cursor.rowcount:
                    tag = cursor.fetchone()[0]
                    log.info('Tag after looking up in tag_tables - %s.', tag)
            checked_tags.append(tag)
        return checked_tags

