def get_requested_day(self, date):
    if True:
        data = dict()
        (day_start, day_end) = self.get_epoch_day(date)
        data['interval'] = {'from': self.convert_local_ts_to_utc(day_start, self.local_timezone), 'to': self.convert_local_ts_to_utc(day_end, self.local_timezone)}
        query = '\n        SELECT TimeStamp, SUM(Power) AS Power \n        FROM DayData \n        WHERE TimeStamp BETWEEN %s AND %s \n        GROUP BY TimeStamp;\n    '
        data['data'] = list()
        for row in self.c.execute(query % (day_start, day_end)):
            data['data'].append({'time': row[0], 'power': row[1]})
        if self.get_datetime(date).date() == datetime.today().date():
            query = '\n            SELECT SUM(EToday) as EToday\n            FROM Inverters;\n            '
        else:
            query = '\n            SELECT SUM(DayYield) AS Power \n            FROM MonthData \n            WHERE TimeStamp BETWEEN %s AND %s\n            GROUP BY TimeStamp\n            ' % (day_start, day_end)
        self.c.execute(query)
        row = self.c.fetchone()
        if row and row[0]:
            data['total'] = row[0]
        else:
            data['total'] = 0
        query = '\n        SELECT MIN(TimeStamp) as Min, MAX(TimeStamp) as Max \n        FROM ( SELECT TimeStamp FROM DayData GROUP BY TimeStamp );\n        '
        self.c.execute(query)
        (first_data, last_data) = self.c.fetchone()
        if first_data:
            data['hasPrevious'] = first_data < day_start
        else:
            data['hasPrevious'] = False
        if last_data:
            data['hasNext'] = last_data > day_end
        else:
            data['hasNext'] = False
        return data

